							v:Notify({ Title = "优化", Content = "阴影已关闭", Duration = 1 })
						else
							v:Notify({ Title = "优化", Content = "阴影已开启", Duration = 1 })
						end
					end

					local function fn74(disableEffects)
						tbl8.disableEffects = disableEffects

						for _, descendant in ipairs(game.Lighting:GetDescendants()) do
							if descendant:IsA("BlurEffect") or descendant:IsA("SunRaysEffect") or descendant:IsA("ColorCorrectionEffect") or descendant:IsA("BloomEffect") or descendant:IsA("DepthOfFieldEffect") then
								pcall(function()
									descendant.Enabled = not disableEffects
								end)
							end
						end

						if disableEffects then
							v:Notify({ Title = "优化", Content = "后期特效已关闭", Duration = 1 })
						else
							v:Notify({ Title = "优化", Content = "后期特效已开启", Duration = 1 })
						end
					end

					local function fn75(simplifyMaterials)
						tbl8.simplifyMaterials = simplifyMaterials

						for _, descendant in ipairs(workspace:GetDescendants()) do
							if descendant:IsA("BasePart") or descendant:IsA("UnionOperation") or descendant:IsA("MeshPart") or descendant:IsA("CornerWedgePart") or descendant:IsA("TrussPart") then
								pcall(function()
									if simplifyMaterials then
										descendant.Material = Enum.Material.Plastic
										descendant.Reflectance = 0
									end
								end)
							end
						end

						if simplifyMaterials then
							v:Notify({ Title = "优化", Content = "材质已简化为 Plastic", Duration = 1 })
						else
							v:Notify({ Title = "优化", Content = "材质已尝试恢复（需重进游戏完全恢复）", Duration = 1 })
						end
					end

					local function fn76(removeParticles)
						tbl8.removeParticles = removeParticles

						for _, descendant in ipairs(workspace:GetDescendants()) do
							if descendant:IsA("ParticleEmitter") or descendant:IsA("Trail") then
								pcall(function()
									if removeParticles then
										descendant.Lifetime = NumberRange.new(0)
									else
										descendant.Lifetime = NumberRange.new(1)
									end
								end)
							end

							if descendant:IsA("Fire") or descendant:IsA("Smoke") or descendant:IsA("Sparkles") then
								pcall(function()
									if removeParticles then
										descendant:Destroy()
									end
								end)
							end
						end

						if removeParticles then
							v:Notify({ Title = "优化", Content = "粒子/火焰/烟雾已禁用", Duration = 1 })
						else
							v:Notify({ Title = "优化", Content = "部分粒子已恢复，火焰/烟雾需重进游戏", Duration = 1 })
						end
